class PrivateCaseReviewIT {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 static final Instant NOW=Instant.parse("2026-10-22T12:00:00Z");
 HikariDataSource ownerSource,runtimeSource;JdbcTemplate owner,jdbc;TransactionTemplate tx,ownerTx;MutableClock clock;JdbcPrivateCaseReview review;PrivateReviewCleanup cleanup;UUID actor,session,organization,requester,caseId;PrivateCaseReview.Target target;PrivateCaseReview.Actor principal;
 static Timestamp at(Instant i){return Timestamp.from(i);}
 static class MutableClock extends Clock{Instant at=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at;}}
 @BeforeAll static void role(){new JdbcTemplate(new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword())).execute("CREATE ROLE private_review_runtime LOGIN PASSWORD 'synthetic-local-only'");}
 @BeforeEach void fixture()throws Exception{
  String database="private_review_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword())).execute("CREATE DATABASE "+database);String url="jdbc:postgresql://"+DB.getHost()+":"+DB.getMappedPort(5432)+"/"+database;MigrationCommand.migrate(url,DB.getUsername(),DB.getPassword());
  ownerSource=pool(url,DB.getUsername(),DB.getPassword());owner=new JdbcTemplate(ownerSource);ownerTx=new TransactionTemplate(new DataSourceTransactionManager(ownerSource));
  owner.execute("GRANT USAGE ON SCHEMA public TO private_review_runtime");owner.execute("GRANT SELECT ON account_identity,platform_account,application_session,application_session_identity,organization,privacy_case_metadata,audit_event TO private_review_runtime");owner.execute("GRANT UPDATE(id) ON account_identity,application_session,organization TO private_review_runtime");owner.execute("GRANT SELECT(id) ON privacy_case TO private_review_runtime");owner.execute("GRANT INSERT ON audit_event TO private_review_runtime");owner.execute(Files.readString(Path.of("audit/private-review-grants.sql")).replace("__RUNTIME_ROLE__","private_review_runtime"));
  runtimeSource=pool(url,"private_review_runtime","synthetic-local-only");jdbc=new JdbcTemplate(runtimeSource);tx=new TransactionTemplate(new DataSourceTransactionManager(runtimeSource));tx.setTimeout(10);clock=new MutableClock();review=new JdbcPrivateCaseReview(jdbc,clock,new UuidGenerator(clock));cleanup=new PrivateReviewCleanup(jdbc,clock);actor=UUID.randomUUID();session=UUID.randomUUID();organization=UUID.randomUUID();requester=UUID.randomUUID();caseId=UUID.randomUUID();target=new PrivateCaseReview.Target(organization,"RS");principal=new PrivateCaseReview.Actor(actor,session,"NATIVE");
  ownerTx.executeWithoutResult(s->{owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'PLATFORM_ADMIN',?,true,'Synthetic operator','ACTIVE'),(?,'BUSINESS',?,true,'Synthetic requester','ACTIVE')",actor,actor+"@example.com",requester,requester+"@example.com");owner.update("INSERT INTO platform_account(id) VALUES(?)",actor);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,'BUYER','RS','RSD','Synthetic','Synthetic','SYN-REVIEW','Synthetic','Synthetic','11000','RS','sr-Latn-RS','ACTIVE',?)",organization,requester);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",requester,organization);});
  owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',?,'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,actor,new byte[32],at(NOW),at(NOW),at(NOW.plusSeconds(43200)),at(NOW));
  owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",actor,at(NOW));owner.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,'RS','EXPORT','Synthetic private request',?)",caseId,requester,organization,at(NOW));
 }
 static HikariDataSource pool(String url,String user,String password){var ds=new HikariDataSource();ds.setJdbcUrl(url);ds.setUsername(user);ds.setPassword(password);ds.setMaximumPoolSize(5);ds.setMinimumIdle(1);ds.setConnectionTimeout(5000);if(!user.equals("private_review_runtime"))ds.setConnectionInitSql("SET narudzbine.operator_change_reference='SYN-PRIVATE-REVIEW'");return ds;}
 @AfterEach void close(){if(runtimeSource!=null)runtimeSource.close();if(ownerSource!=null)ownerSource.close();}
 void guards(){jdbc.queryForList("SELECT id FROM organization WHERE id=? FOR UPDATE",organization);jdbc.queryForList("SELECT id FROM account_identity WHERE id=? FOR UPDATE",actor);jdbc.queryForList("SELECT id FROM application_session WHERE id=? FOR UPDATE",session);}
 PrivateCaseReview.Access authorize(){return tx.execute(s->{guards();return review.authorize(caseId,target,principal,new PrivateCaseReview.Context("Synthetic review reason","SYN-REVIEW"));});}
 PrivateCaseReview.Result disclose(PrivateCaseReview.Access access){return tx.execute(s->{guards();return review.disclose(access);});}
 int direct(PrivateCaseReview.Access access){return jdbc.queryForList("SELECT * FROM public.read_privacy_review(?,?,?,?,?,?)",access.id(),access.nonce(),access.actor().account(),access.actor().session(),access.actor().transport(),at(clock.instant())).size();}
 long audits(String action){return owner.queryForObject("SELECT count(*) FROM audit_event WHERE action=?",Long.class,action);}
 int compact(){return tx.execute(s->cleanup.sweep());}
 @Test void creatorAndSavepointCannotReadThenRollBackTheirOnlyAuthorization(){
  tx.executeWithoutResult(status->{guards();var access=review.authorize(caseId,target,principal,new PrivateCaseReview.Context("Synthetic","SYN"));assertThat(direct(access)).isZero();Object save=status.createSavepoint();assertThat(direct(access)).isZero();status.rollbackToSavepoint(save);status.setRollbackOnly();});assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_access",Long.class)).isZero();
 }
 @Test void committedAccessReturnsOriginalRequestAndBothAuditsWithoutChangingCase(){
  String before=owner.queryForObject("SELECT to_jsonb(c)::text FROM privacy_case c WHERE id=?",String.class,caseId);var access=authorize();var result=disclose(access);assertThat(result.requestReason()).isEqualTo("Synthetic private request");assertThat(result.requesterAccountId()).isEqualTo(requester);assertThat(result.reviewAuthorizationId()).isEqualTo(access.id());assertThat(owner.queryForObject("SELECT to_jsonb(c)::text FROM privacy_case c WHERE id=?",String.class,caseId)).isEqualTo(before);assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_read",Long.class)).isEqualTo(1);assertThat(result.toString()).doesNotContain(result.requestReason());assertThat(access.toString()).isEqualTo("PrivateReviewAccess[redacted]");
 }
 @Test void rollbackOfRestrictedSqlReadCannotRemoveEarlierCommittedAuthorization(){var access=authorize();tx.executeWithoutResult(s->{assertThat(direct(access)).isEqualTo(1);s.setRollbackOnly();});assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();}
 @Test void wrongNonceActorSessionTransportAndCaseBindingsCannotDisclose(){
  var a=authorize();var wrong=new PrivateCaseReview.Access(a.id(),a.caseId(),a.target(),a.actor(),new byte[32],a.expires());assertThatThrownBy(()->disclose(wrong)).isInstanceOf(PrivacyFailure.class);var sessionMismatch=new PrivateCaseReview.Access(a.id(),a.caseId(),a.target(),new PrivateCaseReview.Actor(actor,UUID.randomUUID(),"NATIVE"),a.nonce(),a.expires());assertThatThrownBy(()->disclose(sessionMismatch)).isInstanceOf(PrivacyFailure.class);var transport=new PrivateCaseReview.Access(a.id(),a.caseId(),a.target(),new PrivateCaseReview.Actor(actor,session,"BROWSER"),a.nonce(),a.expires());assertThatThrownBy(()->disclose(transport)).isInstanceOf(PrivacyFailure.class);var otherCase=new PrivateCaseReview.Access(a.id(),UUID.randomUUID(),a.target(),a.actor(),a.nonce(),a.expires());assertThatThrownBy(()->disclose(otherCase)).isInstanceOf(PrivacyFailure.class);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();assertThat(disclose(a).id()).isEqualTo(caseId);
 }
 @Test void exactExpiryAndOneWayDigestRetirementPreventClockRollbackRevival(){
  var access=authorize();clock.at=NOW.plusSeconds(60).minusMillis(1);assertThat(disclose(access).id()).isEqualTo(caseId);clock.at=NOW.plusSeconds(60);assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);assertThat(compact()).isEqualTo(1);clock.at=NOW;assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);assertThatThrownBy(()->owner.update("UPDATE privacy_review_access SET nonce_hash=? WHERE id=?",new byte[32],access.id())).hasStackTraceContaining("immutable");assertThatThrownBy(()->owner.update("DELETE FROM privacy_review_access WHERE id=?",access.id())).hasStackTraceContaining("immutable");
 }
 @Test void qualificationRevokeAndReenableDoNotReviveOldPermit(){var access=authorize();owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",actor);assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);owner.update("UPDATE privacy_operator SET enabled=true,revision=revision+1 WHERE account_id=?",actor);assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);assertThat(disclose(authorize()).id()).isEqualTo(caseId);assertThatThrownBy(()->jdbc.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",actor)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void tokenRotationRevocationAndEpochChangesInvalidateOriginalBinding(){var access=authorize();byte[] rotated=new byte[32];rotated[0]=1;owner.update("UPDATE application_session SET token_hash=? WHERE id=?",rotated,session);assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);var newAccess=authorize();owner.update("UPDATE application_session SET revoked_at=? WHERE id=?",at(NOW),session);assertThatThrownBy(()->disclose(newAccess)).isInstanceOf(PrivacyFailure.class);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();}
 @Test void freshnessEqualityAndInactiveOperatorDenyCreation(){clock.at=NOW.plusSeconds(300);assertThatThrownBy(this::authorize).hasStackTraceContaining("Current operator session required");clock.at=NOW;owner.update("UPDATE account_identity SET state='DEACTIVATED',security_epoch=security_epoch+1 WHERE id=?",actor);assertThatThrownBy(this::authorize).hasStackTraceContaining("Current operator session required");assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isZero();}
 @Test void failedAuthorizationAuditCreatesNoPermitAndFailedReadKeepsEarlierAuthorization(){
  owner.execute("CREATE FUNCTION synthetic_private_review_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='PRIVACY_REVIEW_AUTHORIZED' THEN RAISE EXCEPTION 'Synthetic audit failure';END IF;RETURN NEW;END $$");owner.execute("CREATE TRIGGER tr_synthetic_private_review BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION synthetic_private_review_failure()");try{assertThatThrownBy(this::authorize).hasStackTraceContaining("Synthetic audit failure");}finally{owner.execute("DROP TRIGGER tr_synthetic_private_review ON audit_event");owner.execute("DROP FUNCTION synthetic_private_review_failure()");}assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_access",Integer.class)).isZero();var access=authorize();owner.execute("CREATE FUNCTION synthetic_private_read_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='PRIVACY_CASE_PRIVATE_READ' THEN RAISE EXCEPTION 'Synthetic read audit failure';END IF;RETURN NEW;END $$");owner.execute("CREATE TRIGGER tr_synthetic_private_read BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION synthetic_private_read_failure()");try{assertThatThrownBy(()->disclose(access)).hasStackTraceContaining("Synthetic read audit failure");}finally{owner.execute("DROP TRIGGER tr_synthetic_private_read ON audit_event");owner.execute("DROP FUNCTION synthetic_private_read_failure()");}assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();assertThat(disclose(access).id()).isEqualTo(caseId);
 }
 @Test void runtimeCannotReadPrivateSourceOrEnrollOperatorsAndGateRejectsBroadCredentials(){
  var gate=new PrivateReviewConfiguration();var env=new MockEnvironment().withProperty("identity.http.enabled","true");assertThat(gate.privateReviewPrivilegeGate(jdbc,env)).isNotNull();assertThatThrownBy(()->jdbc.queryForObject("SELECT private_reason FROM privacy_case WHERE id=?",String.class,caseId)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",actor,at(NOW))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->gate.privateReviewPrivilegeGate(owner,env)).isInstanceOf(IllegalStateException.class);owner.execute("GRANT SELECT(private_reason) ON privacy_case TO private_review_runtime");try{assertThatThrownBy(()->gate.privateReviewPrivilegeGate(jdbc,env)).isInstanceOf(IllegalStateException.class);}finally{owner.execute("REVOKE SELECT(private_reason) ON privacy_case FROM private_review_runtime");}assertThat(gate.privateReviewPrivilegeGate(jdbc,env)).isNotNull();
 }
 @Test void oneThousandNonceBoundConvergesWithoutDeletingAuditOrSource(){
  tx.executeWithoutResult(s->{guards();for(int i=0;i<1006;i++)review.authorize(caseId,target,principal,new PrivateCaseReview.Context("Synthetic","SYN"));});clock.at=NOW.plusSeconds(60);assertThat(compact()).isEqualTo(1000);assertThat(compact()).isEqualTo(6);assertThat(compact()).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_access WHERE nonce_hash IS NULL",Integer.class)).isEqualTo(1006);assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1006);
 }
 @Test void revocationWinningActualQualificationLockWaitPreventsNewAuthorization()throws Exception{
  try(var c=ownerSource.getConnection()){c.setAutoCommit(false);int pid;try(var q=c.createStatement();var r=q.executeQuery("SELECT pg_backend_pid()")){r.next();pid=r.getInt(1);}try(var q=c.prepareStatement("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?")){q.setObject(1,actor);q.executeUpdate();}try(var pool=Executors.newSingleThreadExecutor()){var pending=pool.submit(()->{try{authorize();return (Throwable)null;}catch(RuntimeException failure){return failure;}});boolean blocked=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(System.nanoTime()<deadline)if(owner.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)))",Boolean.class,pid)){blocked=true;break;}if(!blocked)c.rollback();assertThat(blocked).isTrue();c.commit();assertThat(pending.get(5,TimeUnit.SECONDS)).isInstanceOf(PrivacyFailure.class);}}
  assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isZero();
 }
 @Test void cleanupSkipsHeldRowAndRollsBackPostWriteFailure()throws Exception{
  var a=authorize();var b=authorize();clock.at=NOW.plusSeconds(60);try(var c=ownerSource.getConnection()){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT id FROM privacy_review_access WHERE id=? FOR UPDATE")){q.setObject(1,a.id());q.execute();}assertThat(compact()).isEqualTo(1);assertThat(owner.queryForObject("SELECT nonce_hash IS NOT NULL FROM privacy_review_access WHERE id=?",Boolean.class,a.id())).isTrue();c.rollback();}owner.execute("CREATE FUNCTION synthetic_nonce_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Synthetic nonce failure';END $$");owner.execute("CREATE TRIGGER tr_synthetic_nonce AFTER UPDATE ON privacy_review_access FOR EACH STATEMENT EXECUTE FUNCTION synthetic_nonce_failure()");try{assertThatThrownBy(this::compact).hasStackTraceContaining("Synthetic nonce failure");assertThat(owner.queryForObject("SELECT nonce_hash IS NOT NULL FROM privacy_review_access WHERE id=?",Boolean.class,a.id())).isTrue();}finally{owner.execute("DROP TRIGGER tr_synthetic_nonce ON privacy_review_access");owner.execute("DROP FUNCTION synthetic_nonce_failure()");}assertThat(compact()).isEqualTo(1);assertThat(owner.queryForObject("SELECT nonce_hash IS NULL AND session_token_hash IS NULL FROM privacy_review_access WHERE id=?",Boolean.class,b.id())).isTrue();
 }
 @Test void nonceCopiesAndDiagnosticRepresentationsNeverExposeTheCapability(){var access=authorize();byte[] copy=access.nonce();Arrays.fill(copy,(byte)0);assertThat(disclose(access).id()).isEqualTo(caseId);assertThat(new PrivateCaseReview.Context("private","context").toString()).isEqualTo("ReviewContext[redacted]");assertThat(access.toString()).doesNotContain(Base64.getEncoder().encodeToString(access.nonce()));}
 @Test void qualificationChangesRequireReferenceAndRetainActualConfigurationPrincipal(){
  assertThatThrownBy(()->ownerTx.executeWithoutResult(s->{owner.execute("SET LOCAL narudzbine.operator_change_reference=''");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",actor);})).hasStackTraceContaining("Reviewed qualification change reference required");assertThat(owner.queryForObject("SELECT enabled FROM privacy_operator WHERE account_id=?",Boolean.class,actor)).isTrue();ownerTx.executeWithoutResult(s->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE-REVIEWED'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",actor);});assertThat(owner.queryForList("SELECT revision FROM privacy_operator_configuration_event WHERE account_id=? ORDER BY revision",Long.class,actor)).containsExactly(1L,2L);assertThat(owner.queryForObject("SELECT change_reference FROM privacy_operator_configuration_event WHERE account_id=? AND revision=2",String.class,actor)).isEqualTo("SYN-REVOKE-REVIEWED");assertThat(owner.queryForObject("SELECT database_login=session_user AND database_role_oid=(SELECT oid FROM pg_roles WHERE rolname=session_user) FROM privacy_operator_configuration_event WHERE account_id=? AND revision=2",Boolean.class,actor)).isTrue();assertThatThrownBy(()->owner.update("DELETE FROM privacy_operator_configuration_event WHERE account_id=?",actor)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.queryForList("SELECT * FROM privacy_operator_configuration_event")).isInstanceOf(org.springframework.dao.DataAccessException.class);
 }
 @Test void proofPairInitialCreatorAndMatchingAuditGuardsRejectForgedShapes(){
  var access=authorize();assertThatThrownBy(()->owner.update("UPDATE privacy_review_access SET nonce_hash=NULL WHERE id=?",access.id())).hasStackTraceContaining("immutable");assertThatThrownBy(()->owner.update("UPDATE privacy_review_access SET nonce_hash=NULL,session_token_hash=NULL,reason='changed' WHERE id=?",access.id())).hasStackTraceContaining("immutable");assertThatThrownBy(()->owner.update("UPDATE privacy_review_access SET created_xid=pg_current_xact_id() WHERE id=?",access.id())).hasStackTraceContaining("immutable");assertThatThrownBy(()->owner.update("INSERT INTO privacy_review_access SELECT p.* FROM privacy_review_access p WHERE id=?",access.id())).hasStackTraceContaining("Initial review proof required");
  UUID forged=UUID.randomUUID();assertThatThrownBy(()->ownerTx.executeWithoutResult(s->{owner.update("INSERT INTO audit_event(id,actor_type,actor_id,action,resource_type,resource_id,outcome,request_id,occurred_at,changed_fields,target_organization_id,target_country) VALUES(?,'PLATFORM_ADMIN',?,'PRIVACY_CASE_PRIVATE_READ','PRIVACY_CASE',?,'SUCCESS',?,?,ARRAY['privateRequest'],?,'RS')",forged,actor,caseId,UUID.randomUUID(),at(NOW),organization);owner.update("INSERT INTO privacy_review_access SELECT(jsonb_populate_record(NULL::privacy_review_access,to_jsonb(p)||jsonb_build_object('id',?::text,'created_xid',pg_current_xact_id()::text))).* FROM privacy_review_access p WHERE id=?",forged,access.id());})).hasStackTraceContaining("Matching review audit required");assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();assertThat(disclose(access).id()).isEqualTo(caseId);
 }
 @Test void currentEpochChangeInvalidatesAnOtherwiseLiveCommittedPermit(){var access=authorize();owner.update("UPDATE account_identity SET security_epoch=security_epoch+1 WHERE id=?",actor);assertThatThrownBy(()->disclose(access)).isInstanceOf(PrivacyFailure.class);assertThat(audits("PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1);assertThat(audits("PRIVACY_CASE_PRIVATE_READ")).isZero();}
 @Test void privilegedTriggersCannotBeAttachedToRuntimeTemporaryTablesEvenAfterAccidentalRegrant()throws Exception{
  try(var connection=runtimeSource.getConnection();var statement=connection.createStatement()){
   statement.execute("CREATE TEMP TABLE forged_qualification(account_id uuid,revision bigint,enabled boolean,created_at timestamptz)");
   statement.execute("CREATE TEMP TABLE forged_read(audit_id uuid,access_id uuid)");
   assertThatThrownBy(()->statement.execute("CREATE TRIGGER forged AFTER INSERT ON forged_qualification FOR EACH ROW EXECUTE FUNCTION public.record_privacy_operator_configuration()" )).isInstanceOf(java.sql.SQLException.class).hasMessageContaining("permission denied");
   assertThatThrownBy(()->statement.execute("CREATE TRIGGER forged AFTER INSERT ON forged_read FOR EACH ROW EXECUTE FUNCTION public.protect_privacy_review_read()" )).isInstanceOf(java.sql.SQLException.class).hasMessageContaining("permission denied");
   owner.execute("GRANT EXECUTE ON FUNCTION record_privacy_operator_configuration(),protect_privacy_review_read() TO private_review_runtime");
   try{
    assertThatThrownBy(()->new PrivateReviewConfiguration().privateReviewPrivilegeGate(jdbc,new MockEnvironment().withProperty("identity.http.enabled","true"))).isInstanceOf(IllegalStateException.class);
    statement.execute("CREATE TRIGGER forged AFTER INSERT ON forged_qualification FOR EACH ROW EXECUTE FUNCTION public.record_privacy_operator_configuration()");
    statement.execute("CREATE TRIGGER forged AFTER INSERT ON forged_read FOR EACH ROW EXECUTE FUNCTION public.protect_privacy_review_read()");
    statement.execute("SET narudzbine.operator_change_reference='SYN-FORGED'");
    assertThatThrownBy(()->statement.execute("INSERT INTO forged_qualification VALUES('"+actor+"',999,true,now())")).isInstanceOf(java.sql.SQLException.class).hasMessageContaining("Qualification source required");
    assertThatThrownBy(()->statement.execute("INSERT INTO forged_read VALUES('"+UUID.randomUUID()+"','"+UUID.randomUUID()+"')")).isInstanceOf(java.sql.SQLException.class).hasMessageContaining("Private review source required");
   }finally{owner.execute("REVOKE EXECUTE ON FUNCTION record_privacy_operator_configuration(),protect_privacy_review_read() FROM private_review_runtime");}
  }
  assertThat(owner.queryForObject("SELECT count(*) FROM privacy_operator_configuration_event WHERE account_id=?",Integer.class,actor)).isEqualTo(1);
  assertThat(disclose(authorize()).id()).isEqualTo(caseId);
 }

}
